-- 设计要求每样食材有分类，中文别名不写入英文原名。
-- 分类编号沿用 USDA food_category，中文名只是该英文类别的译文。
-- 没有官方类别的食材不猜测分类。本批 8262 条都有类别。
-- 家常短名是手工别名，只对应一种食材，不能写成 USDA 官方中文名。

CREATE TABLE food_category (
  id BIGINT NOT NULL AUTO_INCREMENT COMMENT '行号。业务上用 category_code。',
  category_code INT NOT NULL COMMENT 'USDA food_category 编号。不另编一套无法回溯的分类号。',
  zh_name VARCHAR(64) NOT NULL COMMENT '给中文用户看的类别名。这是英文类别的译文，不是中国食物成分表的分类。',
  en_name VARCHAR(200) NOT NULL COMMENT 'USDA 类别英文原名。',
  source_ref VARCHAR(200) NOT NULL COMMENT '类别来源。',
  PRIMARY KEY (id),
  UNIQUE KEY uk_food_category_code (category_code)
) COMMENT='食材分类。一条食材一个类别，配餐时用来区分蔬菜、水果、海鲜和主食。';

