ALTER TABLE food_item
  MODIFY COLUMN category_code INT NOT NULL COMMENT 'USDA 食物类别编号，中文名见 food_category。本批食材都有官方类别。';

-- 中文别名单独成表。display_name 继续保存英文原名。
CREATE TABLE food_alias (
  id BIGINT NOT NULL AUTO_INCREMENT COMMENT '行号。',
  food_item_id VARCHAR(64) NOT NULL COMMENT '对应 food_item.food_item_id。中文名不覆盖英文原名。',
  data_version VARCHAR(32) NOT NULL COMMENT '与食材行相同的数据集版本。换版后别名不自动沿用。',
  alias_name VARCHAR(64) NOT NULL COMMENT '家常叫法。只在人工核对过对应的那一种食材后写入。',
  alias_kind_code INT NOT NULL COMMENT '1 全称对照，2 家常短名。短名全局只能指向一种食材。',
  source_ref VARCHAR(200) NOT NULL COMMENT '别名来源。写明是手工对照，避免被当成官方中文食品名称。',
  PRIMARY KEY (id),
  UNIQUE KEY uk_food_alias_name (alias_name),
  KEY idx_food_alias_item (food_item_id, data_version)
) COMMENT='食材中文别名。和英文原名分开，不能把手工译名当成 USDA 官方中文名。';

